const updateFeedConfig = `-- name: UpdateFeedConfig :one
UPDATE feeds
SET url = $1, filter_include = $2::text[], filter_exclude = $3::text[],
    etag = CASE WHEN $4::boolean THEN NULL ELSE etag END,
    last_modified = CASE WHEN $4::boolean THEN NULL ELSE last_modified END,
    next_refresh_at = COALESCE($5::timestamptz, next_refresh_at),
    updated_at = now()
WHERE id = $6 AND updated_at = $7
RETURNING id, source_id, name, url, enabled, filter_include, filter_exclude, preset, preset_config, register_pending, next_refresh_at, refreshing_until, last_attempt_at, last_success_at, last_outcome, last_error, last_counts, consecutive_failures, etag, last_modified, created_at, updated_at
`

type UpdateFeedConfigParams struct {
	Url               string
	FilterInclude     []string
	FilterExclude     []string
	ResetValidators   bool
	NextRefreshAt     pgtype.Timestamptz
	ID                pgtype.UUID
	ExpectedUpdatedAt pgtype.Timestamptz
}

// Writes the merged URL and filter, guarded by the updated_at they were read
// with. reset_validators drops the conditional-request validators (a changed
// URL or filter needs a full download); next_refresh_at, when given,
// reschedules the feed.
func (q *Queries) UpdateFeedConfig(ctx context.Context, arg UpdateFeedConfigParams) (Feed, error) {
	row := q.db.QueryRow(ctx, updateFeedConfig,
		arg.Url,
		arg.FilterInclude,
		arg.FilterExclude,
		arg.ResetValidators,
		arg.NextRefreshAt,
		arg.ID,
		arg.ExpectedUpdatedAt,
	)
	var i Feed
	err := row.Scan(
		&i.ID,
		&i.SourceID,
		&i.Name,
		&i.Url,
		&i.Enabled,
		&i.FilterInclude,
		&i.FilterExclude,
		&i.Preset,
		&i.PresetConfig,
		&i.RegisterPending,
		&i.NextRefreshAt,
		&i.RefreshingUntil,
		&i.LastAttemptAt,
		&i.LastSuccessAt,
		&i.LastOutcome,
		&i.LastError,
		&i.LastCounts,
		&i.ConsecutiveFailures,
		&i.Etag,
		&i.LastModified,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
